self.addEventListener('install',()=>self.skipWaiting());self.addEventListener('activate',event=>event.waitUntil(self.clients.claim()));self.addEventListener('fetch',event=>{if(event.request.mode==='navigate')event.respondWith(fetch(event.request).catch(()=>new Response('<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>آوای هزاردستان</title><body style="font-family:Tahoma;background:#f5f5ed;color:#315e55;padding:35px"><h2>اتصال اینترنت برقرار نیست</h2><p>برای مشاهده برنامه و ورود به پرتال دوباره به اینترنت متصل شوید.</p><button onclick="location.reload()">تلاش دوباره</button></body></html>',{headers:{'Content-Type':'text/html; charset=utf-8'}})))});
